// Mensagens de ontem
const msgs = $('Busca Mensagens de Ontem').all().map(i => i.json);

// Cobertura de grupos (do nó anterior)
const coverageItems = $input.all();
const coverage = coverageItems.length > 0 ? coverageItems[0].json : {};
const gruposTotalBase = parseInt(coverage.grupos_total_base) || 0;
const gruposComAtividade = parseInt(coverage.grupos_com_atividade) || 0;
const gruposOutroFormato = parseInt(coverage.grupos_outro_formato) || 0;

if (msgs.length === 0) {
  // Log diagnóstico mesmo quando não há mensagens
  console.log(`[TMS] Sem mensagens ontem. Grupos na base (90d): ${gruposTotalBase} | Outro formato (7d): ${gruposOutroFormato}`);
  throw new Error(`Sem mensagens para ontem. Grupos monitorados (90d): ${gruposTotalBase}. Grupos em outro formato: ${gruposOutroFormato}. Verificar integração WhatsApp.`);
}

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const dataRef = yesterday.toISOString().split('T')[0];

const body = JSON.stringify({
  messages: msgs,
  data_referencia: dataRef,
  periodo_inicio: msgs[0].message_timestamp,
  periodo_fim: msgs[msgs.length - 1].message_timestamp,
  grupos_total_base: gruposTotalBase,
  grupos_com_atividade: gruposComAtividade
});

console.log(`[TMS] ${dataRef}: ${msgs.length} msgs | ${gruposComAtividade}/${gruposTotalBase} grupos ativos | outro formato: ${gruposOutroFormato}`);

return [{ json: { body, data_referencia: dataRef, total: msgs.length } }];
